const issue = await tools.github.issue_read({ owner: "danielm5", repo: "tiffcraft", issue_number: 27, method: "get" });
const currentBody = issue.body;

const testingSection = `

## Testing

Existing tests (\`tiffImageTest\`, \`tiffExporterTest\`) only exercise valid fixtures and do not cover any of the defects above. The following new tests must be added so the fixes are verified and protected against regression:

- **ODR / link test:** two translation units each including \`TiffStdOut.hpp\`, compiled and linked together, must succeed. (Can be a standalone compile in CI or a small test target.)
- **ASCII count == 0:** a crafted TIFF with an ASCII entry whose count is 0 must throw (not SEGV).
- **Rational denominator 0:** a crafted TIFF with a rational entry whose denominator is 0 must throw (not SIGFPE).
- **Cyclic IFD offset:** a TIFF whose IFD chain loops must throw or return (not hang).
- **Truncated strip:** a TIFF whose strip data is shorter than declared must throw (not silently produce zeros).
- **\`takeImage()\` move:** after calling \`takeImage()\`, the exporter's internal buffer must be empty (size 0).
- **BYTE printed as integer:** \`operator<<\` on a BYTE entry must output a number, not a character.
- **Example compiles:** \`examples/tiff_image.cpp\` must compile against the current headers.

All existing tests must continue to pass.`;

const newBody = currentBody + testingSection;

const updated = await tools.github.issue_write({
  owner: "danielm5",
  repo: "tiffcraft",
  issue_number: 27,
  method: "update",
  body: newBody
});

console.log("updated:", updated.number, updated.html_url);
return JSON.stringify({ number: updated.number, url: updated.html_url }, null, 2);

